"""Export saved study notebooks for Quartz without running their code cells."""

import argparse
from pathlib import Path
import sys
from urllib.parse import quote

from nbconvert import MarkdownExporter
from nbconvert.preprocessors import ExtractAttachmentsPreprocessor
from nbconvert.writers import FilesWriter
from traitlets.config import Config


GENERATED_MARKER = (
    "<!-- Generated by blog/scripts/convert-notebooks.py; "
    "edit the .ipynb source instead. -->\n"
)
EXCLUDED_DIRECTORIES = {"node_modules", "private", "templates"}


class MarkdownAttachments(ExtractAttachmentsPreprocessor):
    """Keep attachment links valid when notebook or image names contain spaces."""

    def preprocess_cell(self, cell, resources, cell_index):
        cell, resources = super().preprocess_cell(cell, resources, cell_index)
        for filename in cell.get("attachments", {}):
            basename = filename.replace("\\", "/").rsplit("/", 1)[-1]
            target = f"{self.path_name}/{basename}".replace("\\", "/")
            cell.source = cell.source.replace(target, quote(target, safe="/"))
        return cell, resources


def find_notebooks(study_dir: Path) -> list[Path]:
    return sorted(
        notebook
        for notebook in study_dir.rglob("*.ipynb")
        if not any(
            part.startswith(".") or part in EXCLUDED_DIRECTORIES
            for part in notebook.relative_to(study_dir).parts
        )
    )


def check_destination(notebook: Path) -> None:
    markdown_path = notebook.with_suffix(".md")
    generated = markdown_path.exists() and markdown_path.read_text(
        encoding="utf-8"
    ).startswith(GENERATED_MARKER)
    if markdown_path.exists() and not generated:
        raise ValueError(
            f"Refusing to overwrite existing Markdown: {markdown_path}. "
            "Give the notebook a different name."
        )
    assets_dir = notebook.parent / f"{notebook.stem}_files"
    if assets_dir.exists() and not generated:
        raise ValueError(f"Refusing to overwrite existing notebook assets: {assets_dir}")


def convert_notebooks(study_dir: Path) -> int:
    study_dir = study_dir.resolve()
    notebooks = find_notebooks(study_dir)
    # Check all destinations first so a name collision cannot partially convert a batch.
    for notebook in notebooks:
        check_destination(notebook)

    if not notebooks:
        print("Converted 0 notebook(s).")
        return 0

    config = Config()
    config.ExtractAttachmentsPreprocessor.enabled = False
    exporter = MarkdownExporter(config=config)
    exporter.register_preprocessor(MarkdownAttachments, enabled=True)
    for notebook in notebooks:
        assets_dir = notebook.parent / f"{notebook.stem}_files"
        body, resources = exporter.from_filename(
            str(notebook),
            resources={
                "unique_key": notebook.stem,
                "output_files_dir": assets_dir.name,
            },
        )
        # Both output images and Markdown attachments must stay in this asset folder.
        for resource_type in ("outputs", "attachments"):
            for filename in resources.get(resource_type, {}):
                destination = (notebook.parent / filename).resolve()
                if not destination.is_relative_to(assets_dir.resolve()):
                    raise ValueError(f"Notebook asset is outside its folder: {filename}")

        writer = FilesWriter(build_directory=str(notebook.parent))
        writer.write(GENERATED_MARKER + body, resources, notebook_name=notebook.stem)
        print(f"Converted {notebook.relative_to(study_dir)} -> {notebook.stem}.md")

    print(f"Converted {len(notebooks)} notebook(s).")
    return len(notebooks)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "study_directory",
        nargs="?",
        type=Path,
        default=Path(__file__).resolve().parents[2] / "study",
        help="Notebook directory (default: the repository's study directory).",
    )
    args = parser.parse_args()
    if not args.study_directory.is_dir():
        parser.error(f"Notebook directory does not exist: {args.study_directory}")
    try:
        convert_notebooks(args.study_directory)
    except Exception as error:
        print(f"Notebook conversion failed: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
